INSERT INTO sync_daily_summaries (lead_id, date, summary) VALUES
  ('ecd05451-970a-4f70-a056-2ead4ba18910', '2026-10-15', $q$Kami mengirim perkenalan riset dan permintaan maaf baru membalas (HP error). Belum ada balasan.$q$),
  ('d39ff117-d7cc-440a-a624-0e27f7d8b178', '2026-10-15', $q$Kami minta maaf baru membalas lalu mengirim perkenalan riset. Belum ada balasan.$q$),
  ('83c42400-f9f8-4ec7-8b03-d8947f280a30', '2026-10-15', $q$Menolak untuk saat ini ("ndak dulu", mungkin di lain waktu). Atas pertanyaan kami, klinik sudah memakai sistem rekam medis buatan sendiri.$q$),
  ('aaf24ca9-3972-44d6-9b5a-fd90f72e266d', '2026-10-15', $q$Membalas "Maaf masih sibuk"; kami akan menanyakan ulang minggu depan.$q$),
  ('362c2799-fa26-40c7-b89a-f816d4ff5d29', '2026-10-15', $q$Kami minta maaf baru membalas dan mengirim perkenalan riset. Belum ada balasan.$q$),
  ('14674093-c40d-4251-9320-a60afa53a9e2', '2026-10-15', $q$Kami minta maaf baru membalas dan mengirim perkenalan riset. Belum ada balasan.$q$),
  ('99219dcc-159d-4dc8-a65b-3ce49866b3c4', '2026-10-15', $q$Minta dijelaskan ulang maksud dan tujuan; tanya jawab online dan boleh diwakilkan staf. Manajemen belum bersedia tanpa surat resmi, jadi surat kami kirim sore; mereka juga menanyakan keuntungan bagi klinik, dan kami jawab belum banyak yang bisa diberikan karena masih merintis.$q$),
  ('32800d7f-f1b4-4da1-9e76-8a070e9e61ef', '2026-10-15', $q$Kami minta maaf dan mengirim perkenalan riset; sore mereka menjawab perlu menanyakan dulu ke tim manajemen. Kami menyesuaikan dengan ketersediaan pihak praktik.$q$),
  ('617aaa5e-23fe-406c-96a2-b923221652fa', '2026-10-15', $q$Kami menanyakan ulang apakah ada kontak yang bisa dihubungi. Belum ada balasan.$q$),
  ('9ffc7be5-45e5-4f82-b037-3fcfa5373ce1', '2026-10-15', $q$Kami minta maaf baru membalas dan mengirim perkenalan riset. Belum ada balasan.$q$),
  ('e06daa9d-9428-4a8f-a558-b10212dec26e', '2026-10-15', $q$Pagi: masih dipertimbangkan oleh owner. Sore dikonfirmasi manajemennya sama dengan klinik dr. Fery Medika; kami tanya apakah lokasi praktiknya berbeda (ada balasan tanpa teks).$q$),
  ('a2b5eace-6024-4083-b93c-7ab15386e2fb', '2026-10-15', $q$Kami minta maaf baru membalas dan menjelaskan kami dari startup Sahaibat. Belum ada balasan.$q$),
  ('e62c7695-c74a-4d21-875d-e9e3b30a239b', '2026-10-15', $q$Setelah perkenalan, mereka menanyakan asal kantor kami; kami jelaskan dari startup Sahaibat. Belum ada balasan lanjutan.$q$),
  ('12af5002-7545-4923-ba1d-034506fd9da0', '2026-10-15', $q$Kami menanyakan ulang ketersediaan; ada satu balasan tanpa teks (isi belum terbaca).$q$),
  ('ddf157bd-6ae4-4d61-b81d-c9173ef784f7', '2026-10-15', $q$Kami menanyakan apakah ada jadwal senggang hari ini (rencana sesi online Kamis). Belum ada balasan.$q$),
  ('fa1f86f1-c221-4aca-a959-65f02a21cb88', '2026-10-15', $q$Admin meminta surat resmi (instansi berbadan hukum); surat kami kirim dan diteruskan ke manajemen. Kami dihubungkan ke Pak Danang (manajemen Nayaka Malang), yang tidak keberatan riset asal tidak menyangkut data sensitif, dan sesi wawancara disepakati besok (Jumat 16 Okt) sekitar pukul 14.30.$q$),
  ('ca248139-3291-4016-ab22-6f8b8e238abe', '2026-10-15', $q$Kami menanyakan ulang ketersediaan pihak praktik. Belum ada balasan.$q$),
  ('5b689a68-00d6-420a-aefa-7d7997572fbc', '2026-10-15', $q$Pengguna merasa belum memungkinkan pindah dari sistem Khanza ke Sahaibat; saat ini hanya dia yang mencoba. Ia juga menanyakan soal Client ID/Secret/Organization ID untuk integrasi dan mengaku sebelumnya salah memakai ID sandbox lama.$q$),
  ('f30f6a59-cb81-4553-b3a6-7f365151c2cb', '2026-10-15', $q$Menanyakan format wawancara (online via Google Meet) dan isi riset karena klinik masih baru dan belum bekerja sama dengan BPJS; mereka akan menindaklanjuti ke manajemen dan kami minta dikabari.$q$),
  ('0261f398-8474-4929-8608-9cea1b5c1fb9', '2026-10-15', $q$Kami minta maaf baru membalas dan mengirim perkenalan riset. Belum ada balasan.$q$),
  ('a16a15d8-979d-4d8c-9160-6439d74ff8de', '2026-10-15', $q$Kami menanyakan ulang ketersediaan pihak klinik. Belum ada balasan.$q$),
  ('f7cf5d75-5706-48ab-9afa-d89174ad976f', '2026-10-15', $q$Manajemen sedang persiapan kegiatan sehingga belum bisa; kami akan menanyakan ulang minggu depan.$q$),
  ('7d3945fb-050d-4bf7-a20d-49f4c1c4f23c', '2026-10-15', $q$Bu dokter tidak praktik hari ini dan sedang tugas di luar kota, jadi belum ada informasi atas surat kami; sore kami tanya ulang dengan jawaban yang sama.$q$),
